styles:
/* CSS CHÍNH: Nền đen, Tiêu đề trắng, Body trắng, Font Roboto Condensed, KHÔNG KHUNG */
        body { 
            font-family: 'Roboto Condensed', sans-serif; 
            line-height: 1.6; 
            color: #FFFFFF; /* TOÀN BỘ CHỮ BODY MÀU TRẮNG */
            margin: 0; 
            padding: 0; 
            background-color: #000000; /* Nền màu ĐEN TUYỆT ĐỐI */
        }
        .container { 
            /* Đã bỏ background-color, border-radius, và box-shadow để loại bỏ khung */
            max-width: 900px; 
            margin: 20px auto; 
            padding: 20px 30px; /* Giữ padding để nội dung không sát lề */
        }
        h1, h2, h3 { 
            color: #FFFFFF; /* MÀU TRẮNG cho tiêu đề */
            font-weight: 700; 
            text-transform: uppercase; 
            font-family: 'Roboto Condensed' !important; /* Đảm bảo font */
        }
        h1 { 
            font-size: 2.5em; 
            border-bottom: 3px solid #330000; 
            padding-bottom: 15px; 
            margin-bottom: 25px; 
            text-align: center; 
            letter-spacing: 1px; 
        }
        h2 { 
            font-size: 1.8em; 
            margin-top: 30px; 
            border-left: 5px solid #cc0000; /* Đỏ cho đường kẻ bên trái */
            padding-left: 10px; 
        }
        p { 
            margin-bottom: 15px; 
            color: #FFFFFF; /* TOÀN BỘ CHỮ ĐOẠN VĂN MÀU TRẮNG */
        }
        
        /* Highlight và Message Cuối */
        .highlight { 
            font-weight: bold; 
            color: #FFFFFF; /* ĐÃ CHUYỂN THÀNH MÀU TRẮNG */
        }
        .final-message {
            color: #FFFFFF; /* ĐÃ CHUYỂN THÀNH MÀU TRẮNG */
        }

        /* Các thành phần phụ khác */
        .note { 
            background-color: #331a1a; 
            padding: 15px; 
            border-left: 5px solid #ffcc00; 
            margin: 20px 0; 
            border-radius: 5px; 
            color: #f0f0f0; 
        }
        img { 
            max-width: 100%; 
            height: auto; 
            display: block; 
            margin: 20px auto; 
            border-radius: 5px; 
        }
        
        /* Link trong bài */
        a {
            color: #ff3333; /* Màu đỏ sáng cho link để nổi bật */
            text-decoration: none;
        }
        a:hover {
            text-decoration: underline;
        }

        /* Chú thích ảnh */
        em {
            font-size: 0.9em;
            color: #AAAAAA;
            font-style: italic;
        }

        /* Danh sách */
        ul {
            padding-left: 20px;
        }
        li {
            margin-bottom: 10px;
            color: #FFFFFF;
        }
